export interface ViewportPoint {
  x: number;
  y: number;
}

export interface ViewportDimensions {
  width: number;
  height: number;
}

export interface MapTransform {
  scale: number;
  rotationDeg: number;
  translation: ViewportPoint;
  /** Cumulative rotation applied by device heading during active guidance. Degrees (0–360), default 0. */
  headingRotationDeg: number;
}

export interface PinchRotateInput {
  scaleFactor: number;
  rotationDeltaDeg: number;
  focal: ViewportPoint;
  viewport: ViewportDimensions | null | undefined;
}

export const MIN_VIEWPORT_SCALE = 0.5;
export const MAX_VIEWPORT_SCALE = 4;

const DEFAULT_TRANSFORM: MapTransform = {
  scale: 1,
  rotationDeg: 0,
  translation: { x: 0, y: 0 },
  headingRotationDeg: 0,
};

const EPSILON = 1e-6;

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function toRadians(degrees: number): number {
  return (degrees * Math.PI) / 180;
}

function rotatePoint(point: ViewportPoint, angleRad: number): ViewportPoint {
  const cos = Math.cos(angleRad);
  const sin = Math.sin(angleRad);

  return {
    x: point.x * cos - point.y * sin,
    y: point.x * sin + point.y * cos,
  };
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

function isValidViewport(viewport: ViewportDimensions | null | undefined): viewport is ViewportDimensions {
  return (
    !!viewport &&
    isFiniteNumber(viewport.width) &&
    isFiniteNumber(viewport.height) &&
    viewport.width > 0 &&
    viewport.height > 0
  );
}

function clampFocalPoint(focal: ViewportPoint, viewport: ViewportDimensions): ViewportPoint {
  if (!isFiniteNumber(focal.x) || !isFiniteNumber(focal.y)) {
    return {
      x: viewport.width / 2,
      y: viewport.height / 2,
    };
  }

  return {
    x: clamp(focal.x, 0, viewport.width),
    y: clamp(focal.y, 0, viewport.height),
  };
}

export function createInitialMapTransform(): MapTransform {
  return {
    scale: DEFAULT_TRANSFORM.scale,
    rotationDeg: DEFAULT_TRANSFORM.rotationDeg,
    translation: { ...DEFAULT_TRANSFORM.translation },
    headingRotationDeg: DEFAULT_TRANSFORM.headingRotationDeg,
  };
}

export function clampViewportScale(scale: number): number {
  if (!isFiniteNumber(scale)) {
    return DEFAULT_TRANSFORM.scale;
  }

  return clamp(scale, MIN_VIEWPORT_SCALE, MAX_VIEWPORT_SCALE);
}

export function normalizeRotationDeg(rotationDeg: number): number {
  if (!isFiniteNumber(rotationDeg)) {
    return DEFAULT_TRANSFORM.rotationDeg;
  }

  return ((((rotationDeg + 180) % 360) + 360) % 360) - 180;
}

export function worldFromScreen(screenPoint: ViewportPoint, transform: MapTransform): ViewportPoint {
  const scale = clampViewportScale(transform.scale);
  const normalizedRotation = normalizeRotationDeg(transform.rotationDeg);

  const translated = {
    x: screenPoint.x - transform.translation.x,
    y: screenPoint.y - transform.translation.y,
  };

  const unrotated = rotatePoint(translated, -toRadians(normalizedRotation));

  return {
    x: unrotated.x / scale,
    y: unrotated.y / scale,
  };
}

export function screenFromWorld(worldPoint: ViewportPoint, transform: MapTransform): ViewportPoint {
  const scale = clampViewportScale(transform.scale);
  const normalizedRotation = normalizeRotationDeg(transform.rotationDeg);

  const scaled = {
    x: worldPoint.x * scale,
    y: worldPoint.y * scale,
  };

  const rotated = rotatePoint(scaled, toRadians(normalizedRotation));

  return {
    x: rotated.x + transform.translation.x,
    y: rotated.y + transform.translation.y,
  };
}

export function applyPanDelta(transform: MapTransform, delta: ViewportPoint): MapTransform {
  if (!isFiniteNumber(delta.x) || !isFiniteNumber(delta.y)) {
    return transform;
  }

  const nextTranslation = {
    x: transform.translation.x + delta.x,
    y: transform.translation.y + delta.y,
  };

  if (!isFiniteNumber(nextTranslation.x) || !isFiniteNumber(nextTranslation.y)) {
    return transform;
  }

  return {
    ...transform,
    translation: nextTranslation,
  };
}

export function applyPinchRotate(transform: MapTransform, input: PinchRotateInput): MapTransform {
  if (!isValidViewport(input.viewport)) {
    return transform;
  }

  if (
    !isFiniteNumber(input.scaleFactor) ||
    !isFiniteNumber(input.rotationDeltaDeg) ||
    input.scaleFactor <= 0
  ) {
    return transform;
  }

  const focalPoint = clampFocalPoint(input.focal, input.viewport);
  const worldAnchor = worldFromScreen(focalPoint, transform);

  const nextScale = clampViewportScale(transform.scale * input.scaleFactor);
  const nextRotation = normalizeRotationDeg(transform.rotationDeg + input.rotationDeltaDeg);

  const projectedAnchor = screenFromWorld(worldAnchor, {
    scale: nextScale,
    rotationDeg: nextRotation,
    translation: { x: 0, y: 0 },
    headingRotationDeg: 0,
  });

  const nextTranslation = {
    x: focalPoint.x - projectedAnchor.x,
    y: focalPoint.y - projectedAnchor.y,
  };

  if (!isFiniteNumber(nextTranslation.x) || !isFiniteNumber(nextTranslation.y)) {
    return transform;
  }

  return {
    scale: nextScale,
    rotationDeg: nextRotation,
    translation: nextTranslation,
    headingRotationDeg: transform.headingRotationDeg,
  };
}

export function mapTransformsEqual(a: MapTransform, b: MapTransform): boolean {
  return (
    Math.abs(a.scale - b.scale) < EPSILON &&
    Math.abs(a.rotationDeg - b.rotationDeg) < EPSILON &&
    Math.abs(a.translation.x - b.translation.x) < EPSILON &&
    Math.abs(a.translation.y - b.translation.y) < EPSILON &&
    Math.abs(a.headingRotationDeg - b.headingRotationDeg) < EPSILON
  );
}

/**
 * Applies device heading rotation to an existing transform.
 * When headingDegrees is null, returns existing unchanged.
 * When non-null, returns existing with headingRotationDeg set to headingDegrees.
 */
export function applyHeadingRotation(
  existing: MapTransform,
  headingDegrees: number | null,
): MapTransform {
  if (headingDegrees === null) {
    return existing;
  }
  return {
    ...existing,
    headingRotationDeg: headingDegrees,
  };
}

/**
 * Guidance state machine — pure computation, no React dependencies.
 *
 * Core types and helper functions for confidence-gated turn-by-turn navigation.
 * Drives the live guidance UI overlay and reroute logic.
 */

import type { DirectionStep, NormalizedNodeRecord } from '../domain/navGraph';
import type { PathResult } from '../domain/navGraph';
import type { RouteSessionReadyState } from './routeSessionState';
import type { NormalizedPoint } from '../../src/shared/gps';

// ============================================================
// Core types
// ============================================================

/**
 * GPS and heading confidence classification.
 *
 * Used by `deriveConfidence` to determine how aggressively
 * the guidance engine trusts the current position fix.
 */
export type ConfidenceLevel = 'high' | 'medium' | 'low' | 'none';

/**
 * Phase of the guidance state machine.
 *
 * State transitions are governed by `deriveNextPhase`:
 * - `idle`          → Initial state; no route loaded
 * - `low-confidence` → Route loaded, but GPS/heading signal is weak
 * - `guiding`       → Route active with confident position; advancing steps
 * - `rerouting`     → Off-route detected, computing new path
 * - `arrived`        → User has reached the destination
 */
export type GuidancePhase =
  | 'idle'
  | 'low-confidence'
  | 'guiding'
  | 'rerouting'
  | 'arrived';

/**
 * Core guidance state for live navigation.
 *
 * Carries the route, current position, and confidence signals needed
 * to drive step advancement and reroute decisions.
 */
export interface GuidanceState {
  phase: GuidancePhase;
  /** The route being followed — must be in 'ready' phase. */
  route: RouteSessionReadyState;
  /** Index of the active DirectionStep (0-based). */
  currentStepIndex: number;
  /** User's current position in normalized [0,1] map space. */
  snappedPosition: NormalizedPoint;
  /** Nearest walkable node ID to the snapped position. */
  snappedNodeId: string;
  /** Device compass heading in degrees (0–360), null if unavailable. */
  heading: number | null;
  /** Heading accuracy in degrees, null if unavailable. */
  headingConfidence: number | null;
  /** Classification of current position fix quality. */
  positionConfidence: ConfidenceLevel;
  /** Unix timestamp (ms) of the last position fix. */
  lastFixTimestamp: number;
  /** Unix timestamp (ms) when off-route was first detected, null if on-route. */
  offRouteDetectedAt: number | null;
  /** Consecutive fixes where off-route was detected. */
  offRouteFixCount: number;
  /** Result of the last reroute computation, null if no reroute has been attempted. */
  rerouteResult: PathResult | null;
  /** Floor ID of the current snapped node, null if not on any floor. */
  currentFloorId: number | null;
}

// ============================================================
// Helper function input types
// ============================================================

export interface PositionFix {
  readonly isConfident: boolean;
  readonly accuracyMeters: number | null;
}

export interface HeadingFix {
  readonly headingDegrees: number | null;
  readonly accuracyDegrees: number | null;
}

// ============================================================
// Pure helper functions
// ============================================================

/**
 * Derive the GPS/heading confidence level from position and heading fixes.
 *
 * Confidence levels:
 * - `high`:   GPS fix is confident AND heading accuracy ≤ 15°
 * - `medium`: GPS fix is confident but heading is missing or unreliable (> 15°)
 * - `low`:    GPS fix not confident but finite (accuracy exists)
 * - `none`:   No GPS fix or infinite accuracy
 */
export function deriveConfidence(
  positionFix: PositionFix,
  headingFix: HeadingFix,
): ConfidenceLevel {
  // none: no GPS fix (null) or infinite accuracy
  if (positionFix.accuracyMeters == null || !Number.isFinite(positionFix.accuracyMeters)) {
    return 'none';
  }

  // low: GPS fix not confident but finite (accuracy exists but > threshold)
  if (!positionFix.isConfident) {
    return 'low';
  }

  // medium: GPS confident but heading missing or unreliable
  if (
    headingFix.headingDegrees == null
    || headingFix.accuracyDegrees == null
    || !Number.isFinite(headingFix.accuracyDegrees)
    || headingFix.accuracyDegrees > 15
  ) {
    return 'medium';
  }

  // high: GPS confident AND heading reliable (≤ 15°)
  return 'high';
}

// ============================================================
// Private helpers
// ============================================================

/**
 * Build an ordered coordinate lookup from a path and its route state.
 * Looks for a nodeById map on the path (production) or falls back to
 * extracting coordinates directly from the node IDs using route.path.nodeById.
 *
 * The path may carry nodeById as an extended property (production path),
 * or the coordinates are resolved via route.path.nodeById (test path).
 */
function buildCoordLookup(
  path: PathResult,
  route: RouteSessionReadyState,
): Map<number, { x: number; y: number }> {
  const coords = new Map<number, { x: number; y: number }>();

  // Try path.nodeById first (production extension pattern)
  const pathAsExtended = path as PathResult & { nodeById?: Map<string, NormalizedNodeRecord> };
  if (pathAsExtended.nodeById && typeof pathAsExtended.nodeById.get === 'function') {
    const nodeById = pathAsExtended.nodeById;
    for (let i = 0; i < path.nodeIds.length; i++) {
      const record = nodeById.get(path.nodeIds[i]);
      if (record) {
        coords.set(i, { x: record.node.x, y: record.node.y });
      }
    }
    return coords;
  }

  // Fallback: resolve via route.path.nodeById (test / production NormalizedNavGraph pattern)
  const routePathAsGraph = route.path as PathResult & { nodeById?: Map<string, NormalizedNodeRecord> };
  const nodeById = routePathAsGraph.nodeById;
  if (nodeById && typeof nodeById.get === 'function') {
    for (let i = 0; i < path.nodeIds.length; i++) {
      const record = nodeById.get(path.nodeIds[i]);
      if (record) {
        coords.set(i, { x: record.node.x, y: record.node.y });
      }
    }
  }

  return coords;
}

/**
 * Compute perpendicular (orthogonal) distance from a point to a line segment.
 *
 * Returns the minimum distance from `point` to any point on the segment
 * between `segStart` and `segEnd`.
 *
 * Uses the standard point-to-segment formula:
 * Let t = dot(P - segStart, segEnd - segStart) / |segEnd - segStart|²
 * Clamp t to [0, 1] (to stay on the segment)
 * Closest point = segStart + t * (segEnd - segStart)
 * Distance = |P - closest_point|
 */
function pointToSegmentDistance(
  point: NormalizedPoint,
  segStart: { x: number; y: number },
  segEnd: { x: number; y: number },
): number {
  const dx = segEnd.x - segStart.x;
  const dy = segEnd.y - segStart.y;
  const lenSq = dx * dx + dy * dy;

  // Degenerate segment (start === end): return distance to the point
  if (lenSq === 0) {
    return Math.sqrt((point.x - segStart.x) ** 2 + (point.y - segStart.y) ** 2);
  }

  // Parameter t for the projection of P onto the segment line
  const t = Math.max(
    0,
    Math.min(
      1,
      ((point.x - segStart.x) * dx + (point.y - segStart.y) * dy) / lenSq,
    ),
  );

  const closestX = segStart.x + t * dx;
  const closestY = segStart.y + t * dy;

  return Math.sqrt((point.x - closestX) ** 2 + (point.y - closestY) ** 2);
}

// ============================================================
// Public route-geometry helpers
// ============================================================

/**
 * Returns true when the user's position is off the active route segment.
 *
 * Detects deviation by measuring perpendicular distance from the current
 * position to the current path segment (from path.nodeIds[currentStepIndex]
 * to path.nodeIds[currentStepIndex + 1]).
 *
 * @param position     User's current snapped position
 * @param currentStepIndex  Which step in the route is active
 * @param path         The current route path
 * @param route        The route session state (provides normalized graph nodeById)
 * @param threshold    Deviation threshold in normalized units (default: 0.05)
 */
export function isOffRoute(
  position: NormalizedPoint,
  currentStepIndex: number,
  path: PathResult,
  route: RouteSessionReadyState,
  threshold = 0.05,
): boolean {
  if (!path.found || path.nodeIds.length < 2) return false;

  const coords = buildCoordLookup(path, route);

  // When at or beyond the last segment, use distance to the final node
  if (currentStepIndex >= path.nodeIds.length - 1) {
    const lastNode = coords.get(path.nodeIds.length - 1);
    if (!lastNode) return false;

    const dist = Math.sqrt(
      (position.x - lastNode.x) ** 2 + (position.y - lastNode.y) ** 2,
    );
    return dist > threshold;
  }

  const startNode = coords.get(currentStepIndex);
  const endNode = coords.get(currentStepIndex + 1);
  if (!startNode || !endNode) return false;

  const distance = pointToSegmentDistance(position, startNode, endNode);
  return distance > threshold;
}

/**
 * Returns true when the user has reached the waypoint at the start of the next step.
 *
 * Uses the same perpendicular-distance approach as `isOffRoute` but with a
 * smaller threshold so that near-passing doesn't trigger an advance mid-segment.
 *
 * @param position        User's current snapped position
 * @param currentStepIndex  Index of the current step (advance check goes to step + 1)
 * @param path            The current route path
 * @param route           The route session state (provides normalized graph nodeById)
 * @param advanceThreshold  Proximity threshold for triggering advance (default: 0.03)
 */
export function shouldAdvanceStep(
  position: NormalizedPoint,
  currentStepIndex: number,
  path: PathResult,
  route: RouteSessionReadyState,
  advanceThreshold = 0.03,
): boolean {
  if (!path.found || path.nodeIds.length < 2) return false;

  const coords = buildCoordLookup(path, route);

  // If the next step index is beyond the node list, use the last node
  const nextStepIdx = currentStepIndex + 1;
  if (nextStepIdx >= path.nodeIds.length) {
    const lastNode = coords.get(path.nodeIds.length - 1);
    if (!lastNode) return false;
    return (
      Math.sqrt(
        (position.x - lastNode.x) ** 2 + (position.y - lastNode.y) ** 2,
      ) <= advanceThreshold
    );
  }

  const startNode = coords.get(currentStepIndex);
  const endNode = coords.get(nextStepIdx);
  if (!startNode || !endNode) return false;

  const distance = pointToSegmentDistance(position, startNode, endNode);
  return distance <= advanceThreshold;
}

/**
 * Derive the next phase from current state and signals.
 *
 * Phase transition rules:
 * - `idle`          → `isConfident` ? 'guiding' : 'low-confidence'
 * - `low-confidence` → `isConfident` ? 'guiding' : stay 'low-confidence'
 * - `guiding`       → `hasArrived` ? 'arrived'
 *                    → `offRouteFixCount >= rerouteConfirmFixes` ? 'rerouting'
 *                    → stay 'guiding'
 * - `rerouting`     → always transitions to 'guiding' (assumes reroute succeeded)
 * - `arrived`       → stays 'arrived'
 *
 * @param state                  Current guidance state
 * @param isConfident            Whether current position is high or medium confidence
 * @param hasArrived             Whether the user has arrived at the destination
 * @param offRouteFixCount       Number of consecutive off-route position fixes
 * @param rerouteConfirmFixes    Fixes required before triggering reroute (default: 3)
 */
export function deriveNextPhase(
  state: GuidanceState,
  isConfident: boolean,
  hasArrived: boolean,
  offRouteFixCount: number,
  rerouteConfirmFixes = 3,
): GuidancePhase {
  switch (state.phase) {
    case 'idle':
      return isConfident ? 'guiding' : 'low-confidence';

    case 'low-confidence':
      return isConfident ? 'guiding' : 'low-confidence';

    case 'guiding':
      if (hasArrived) return 'arrived';
      if (offRouteFixCount >= rerouteConfirmFixes) return 'rerouting';
      return 'guiding';

    case 'rerouting':
      // Assumes the caller has set rerouteResult; transitions back to guiding
      return 'guiding';

    case 'arrived':
      return 'arrived';
  }
}

/**
 * Return the active DirectionStep for the current step index.
 *
 * Returns null when there is no active route, no directions have been generated,
 * or the current step index is out of bounds.
 */
export function getActiveStep(state: GuidanceState): DirectionStep | null {
  const { route, currentStepIndex } = state;
  if (route.phase !== 'ready') return null;
  if (!route.directions) return null;
  const { steps } = route.directions;
  if (currentStepIndex < 0 || currentStepIndex >= steps.length) return null;
  return steps[currentStepIndex] ?? null;
}

/**
 * Derive floor context from a GuidanceState snapshot.
 *
 * Returns the floorId of the current snapped node, or null when
 * the user is not on any floor (idle or no snapped node).
 */
export function deriveFloorContext(state: GuidanceState): number | null {
  return state.currentFloorId ?? null;
}

/**
 * LiveGuidanceOverlay — real-time guidance overlay driven by GuidanceState.
 *
 * Conditionally renders one of five UI variants based on `guidanceState.phase`:
 * - `idle`          → nothing
 * - `low-confidence` → orange banner prompting position confirmation
 * - `guiding`       → step card with instruction, icon, distance, progress
 * - `rerouting`     → blue banner with spinner
 * - `arrived`       → green celebration card
 */

import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';
import { useRef, useState } from 'react';

import { getActiveStep, type GuidanceState } from '../../routing/guidanceState';
import type { DirectionStep, NormalizedFloorRecord } from '../../domain/navGraph';
import { ConfidenceIndicator, type ConfidenceLevel } from './ConfidenceIndicator';

// ─── Step icon helpers (mirrors RoutePreview) ────────────────────────────────

const STEP_ICONS: Record<string, string> = {
  'straight': '↑',
  'turn-left': '←',
  'turn-right': '→',
  'sharp-left': '↙',
  'sharp-right': '↘',
  'arrive': '🏁',
  'accessible': '♿',
  'stairs-up': '⬆',
  'stairs-down': '⬇',
  'elevator': '🛗',
  'ramp': '♿',
};

function stepIcon(step: DirectionStep): string {
  return STEP_ICONS[step.icon] ?? '→';
}

// ─── Distance formatting ─────────────────────────────────────────────────────

/**
 * Format a normalized distance as a human-readable string.
 * Normalized coordinate space → approximate real distance (50 m per unit).
 */
function formatDistance(norm: number): string {
  const meters = Math.round(norm * 50);
  if (meters < 1) return '<1m';
  if (meters >= 1000) return `${(meters / 1000).toFixed(1)}km`;
  return `${meters}m`;
}

/**
 * Sum of distances for all steps from currentStepIndex onward.
 */
function remainingDistance(state: GuidanceState): number {
  const { route, currentStepIndex } = state;
  if (route.phase !== 'ready' || !route.directions) return 0;
  return route.directions.steps
    .slice(currentStepIndex)
    .reduce((sum, s) => sum + s.distanceM, 0);
}

// ─── Props ───────────────────────────────────────────────────────────────────

export interface LiveGuidanceOverlayProps {
  guidanceState: GuidanceState;
  onConfirmPosition: () => void;
  onStopGuidance: () => void;
  /** Floor ID of the current snapped position. */
  floorId?: number | null;
  /** Floor lookup map for display labels. */
  floorMap?: Map<number, NormalizedFloorRecord>;
  /** When true, applies accessible mode styling to elevator/ramp steps. */
  accessibleMode?: boolean;
}

// ─── Sub-components ───────────────────────────────────────────────────────────

/** Low-confidence banner: orange/yellow background, confirm button. */
function LowConfidenceBanner({
  onConfirmPosition,
  floorId,
  floorMap,
}: {
  onConfirmPosition: () => void;
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
}) {
  const floorLabel = floorId && floorMap ? floorMap.get(floorId)?.floor.floorNumber ?? floorId : null;

  return (
    <View style={styles.lowConfidenceBanner} testID="low-confidence-banner">
      <View style={styles.bannerRow}>
        <ConfidenceIndicator confidence="low" />
        <Text style={styles.lowConfidenceText}>
          Can't confirm your location.{'\n'}
          Tap the map to confirm where you are, or move to an open area.
          {floorLabel != null ? `\nYou are on Floor ${floorLabel}.` : ''}
        </Text>
      </View>
      <Pressable style={styles.confirmButton} onPress={onConfirmPosition} testID="confirm-position-btn">
        <Text style={styles.confirmButtonText}>Confirm location</Text>
      </Pressable>
    </View>
  );
}

/** Rerouting banner: blue background with spinner. */
function ReroutingBanner() {
  return (
    <View style={styles.reroutingBanner} testID="rerouting-banner">
      <ActivityIndicator color="#38bdf8" size="small" />
      <Text style={styles.reroutingText}>Recalculating your route...</Text>
    </View>
  );
}

/** Main guiding card: step instruction, icon, distance, progress. */
function GuidingCard({
  state,
  onStopGuidance,
  floorId,
  floorMap,
  accessibleMode,
}: {
  state: GuidanceState;
  onStopGuidance: () => void;
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
  accessibleMode?: boolean;
}) {
  const activeStep = getActiveStep(state);
  const { route, currentStepIndex, positionConfidence } = state;

  const totalSteps = route.phase === 'ready' && route.directions
    ? route.directions.steps.length
    : 0;
  const progressLabel = `Step ${currentStepIndex + 1} of ${totalSteps}`;
  const remaining = remainingDistance(state);

  const isAccessibleStep = activeStep?.icon === 'elevator' || activeStep?.icon === 'ramp';
  const highlightAccessible = accessibleMode && isAccessibleStep;

  let instruction = activeStep?.instruction ?? 'Navigating...';
  if (highlightAccessible) {
    instruction = `${instruction} (accessible)`;
  }

  const icon = activeStep ? stepIcon(activeStep) : '→';

  return (
    <View style={styles.guidingCard} testID="guiding-card">
      {/* Top row: step icon + instruction */}
      <View style={styles.stepRow}>
        <View style={[styles.stepIconContainer, highlightAccessible && styles.stepIconContainerAccessible]}>
          <Text style={[styles.stepIcon, highlightAccessible && styles.stepIconAccessible]}>{icon}</Text>
        </View>
        <Text style={styles.instructionText} numberOfLines={2}>
          {instruction}
        </Text>
        <ConfidenceIndicator confidence={positionConfidence} />
      </View>

      {/* Floor badge row */}
      <FloorBadge floorId={floorId} floorMap={floorMap} />

      {/* Bottom row: distance + progress + end button */}
      <View style={styles.bottomRow}>
        <Text style={styles.distanceText}>{formatDistance(remaining)} remaining</Text>
        <Text style={styles.progressText}>{progressLabel}</Text>
        <Pressable onPress={onStopGuidance} testID="stop-guidance-btn">
          <Text style={styles.endButton}>End guidance</Text>
        </Pressable>
      </View>
    </View>
  );
}

/** Arrived celebration card. */
function ArrivedCard({
  state,
  onStopGuidance,
}: {
  state: GuidanceState;
  onStopGuidance: () => void;
}) {
  const destLabel =
    state.route.phase === 'ready' && state.route.destination
      ? state.route.destination.label
      : 'Destination';

  return (
    <View style={styles.arrivedCard} testID="arrived-card">
      <Text style={styles.checkmark}>✅</Text>
      <Text style={styles.arrivedTitle}>You've arrived!</Text>
      <Text style={styles.arrivedDest}>{destLabel}</Text>
      <Pressable style={styles.doneButton} onPress={onStopGuidance} testID="done-btn">
        <Text style={styles.doneButtonText}>Done</Text>
      </Pressable>
    </View>
  );
}

/** Floor badge — shows current floor label next to step icon in the guiding card. */
function FloorBadge({
  floorId,
  floorMap,
}: {
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
}) {
  if (!floorId || !floorMap) return null;
  const record = floorMap.get(floorId);
  if (!record) return null;
  return (
    <View style={styles.floorBadge} testID="floor-badge">
      <Text style={styles.floorBadgeText}>Floor {record.floor.floorNumber}</Text>
    </View>
  );
}

/** Floor transition banner — briefly shown for 2500 ms when floor changes. */
function FloorTransitionBanner({
  floorId,
  floorMap,
}: {
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
}) {
  const prevFloorIdRef = useRef<number | null>(null);
  const [visible, setVisible] = useState(false);
  const [displayFloorId, setDisplayFloorId] = useState<number | null>(null);

  const safeFloorId: number | null = floorId ?? null;

  if (safeFloorId !== null && safeFloorId !== prevFloorIdRef.current && prevFloorIdRef.current !== null) {
    prevFloorIdRef.current = safeFloorId;
    const label = floorMap?.get(safeFloorId)?.floor.floorNumber ?? safeFloorId;
    setDisplayFloorId(safeFloorId);
    setVisible(true);
    setTimeout(() => setVisible(false), 2500);
  } else if (safeFloorId !== null) {
    prevFloorIdRef.current = safeFloorId;
  }

  if (!visible || displayFloorId === null) return null;

  const label = floorMap?.get(displayFloorId)?.floor.floorNumber ?? displayFloorId;

  return (
    <View style={styles.floorTransitionBanner} testID="floor-transition-banner">
      <Text style={styles.floorTransitionText}>Now on Floor {label}</Text>
    </View>
  );
}

// ─── Main component ──────────────────────────────────────────────────────────

export function LiveGuidanceOverlay({
  guidanceState,
  onConfirmPosition,
  onStopGuidance,
  floorId,
  floorMap,
  accessibleMode,
}: LiveGuidanceOverlayProps) {
  const { phase } = guidanceState;

  if (phase === 'idle') return null;

  if (phase === 'low-confidence') {
    return <LowConfidenceBanner onConfirmPosition={onConfirmPosition} floorId={floorId} floorMap={floorMap} />;
  }

  if (phase === 'rerouting') {
    return <ReroutingBanner />;
  }

  if (phase === 'arrived') {
    return <ArrivedCard state={guidanceState} onStopGuidance={onStopGuidance} />;
  }

  // phase === 'guiding'
  return (
    <>
      <FloorTransitionBanner floorId={floorId} floorMap={floorMap} />
      <GuidingCard
        state={guidanceState}
        onStopGuidance={onStopGuidance}
        floorId={floorId}
        floorMap={floorMap}
        accessibleMode={accessibleMode}
      />
    </>
  );
}

